<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{afterSalesApi,type AfterSaleReason}from'@/api/after-sales';const rows=ref<AfterSaleReason[]>([]),visible=ref(false),editing=ref<string|null>(null);const form=reactive({name:'',sort:0,status:'ACTIVE' as 'ACTIVE'|'INACTIVE'});async function load(){rows.value=await afterSalesApi.reasons()}function open(row?:AfterSaleReason){editing.value=row?.id??null;Object.assign(form,row?{name:row.name,sort:row.sort,status:row.status}:{name:'',sort:0,status:'ACTIVE'});visible.value=true}async function save(){if(editing.value)await afterSalesApi.updateReason(editing.value,form);else await afterSalesApi.createReason(form);visible.value=false;ElMessage.success('售后原因已保存');await load()}async function remove(row:AfterSaleReason){await ElMessageBox.confirm('已被使用的原因将自动停用，确认继续？','删除原因');await afterSalesApi.deleteReason(row.id);await load()}onMounted(load)</script>
<template><section><div class="page-heading"><div><p class="eyebrow">AFTER SALES SETTINGS</p><h1>售后原因设置</h1></div><ElButton type="primary" @click="open()">新增原因</ElButton></div><div class="management-card"><ElTable :data="rows"><ElTableColumn prop="name" label="原因"/><ElTableColumn prop="sort" label="排序" width="100"/><ElTableColumn prop="status" label="状态" width="120"/><ElTableColumn label="操作" width="160"><template #default="{row}"><ElButton link @click="open(row)">编辑</ElButton><ElButton link type="danger" @click="remove(row)">删除</ElButton></template></ElTableColumn></ElTable></div><ElDialog v-model="visible" :title="editing?'编辑原因':'新增原因'" width="450px"><ElForm label-width="80px"><ElFormItem label="名称"><ElInput v-model="form.name"/></ElFormItem><ElFormItem label="排序"><ElInputNumber v-model="form.sort" :min="0"/></ElFormItem><ElFormItem label="状态"><ElSwitch v-model="form.status" active-value="ACTIVE" inactive-value="INACTIVE"/></ElFormItem></ElForm><template #footer><ElButton @click="visible=false">取消</ElButton><ElButton type="primary" :disabled="!form.name.trim()" @click="save">保存</ElButton></template></ElDialog></section></template>
